#include <stdio.h>
#include <stdint.h>

static void write_pr(uint32_t *pr, uint32_t v) {
    *pr &= ~v;   // hardware: writing 1 clears
}

int main(void) {
    uint32_t a = 0x28, b = 0x28;
    write_pr(&a, a | (1u << 5));  // PR |= 1<<5
    write_pr(&b, 1u << 5);        // PR  = 1<<5
    printf("0x%X 0x%X", a, b);
}

#include <stdio.h>

int main(void) {
    int pin[] = {1, 0, 0, 1};  // idle, press, hold, release
    int change = 0, falling = 0;
    for (int i = 1; i < 4; i++) {
        if (pin[i] != pin[i-1]) change++;
        if (pin[i-1] == 1 && pin[i] == 0) falling++;
    }
    printf("%d %d", change, falling);
}

